"""Exact cumulative progression/resource tables from the supplied sIO runtime.

The payload includes item E/V/C paths, Relic/Core/Transmute costs, survivor and
pet star costs, Tech resonance tables, and mount shard/core/sync tables. It is
compressed only to keep generated source compact.
"""
from __future__ import annotations
import base64
import json
import zlib

_COMPRESSED = ""
SIO_PROGRESSION_DATA = json.loads(zlib.decompress(base64.b64decode(_COMPRESSED)).decode("utf-8"))
